  "implementation": "def solve(case):
    # Extract fields
    word_token_indices = case['word_token_indices']
    word_labels = case['word_labels']
    token_count = case['token_count']

    # Initialize token_labels with None to track unset
    token_labels = [None] * token_count

    # Broadcast each word's label to its token indices
    for indices, label in zip(word_token_indices, word_labels):
        for idx in indices:
            # Validate index range
            if not (0 <= idx < token_count):
                raise ValueError(f'Token index {idx} out of range')
            # Detect overlap
            if token_labels[idx] is not None:
                raise ValueError(f'Overlapping token index {idx}')
            token_labels[idx] = label

    # Validate no uncovered tokens
    if any(label is None for label in token_labels):
        raise ValueError('Some token indices are not covered')

    # Compute kept_indices where label == 1
    kept_indices = [i for i, label in enumerate(token_labels) if label == 1]

    return {
        'kept_indices': kept_indices,
        'token_labels': token_labels
    }"
}
